"""Child-process entry point for IsolatedToolHandler."""
from __future__ import annotations

import base64
import json
import pickle
import sys
from typing import Any

_RESULT_PREFIX = "__JARVIS_ISOLATED_RESULT__"


def _execute(request: dict[str, Any]) -> dict[str, Any]:
    descriptor = request.get("descriptor")
    args = request.get("args")
    if not isinstance(descriptor, str) or not isinstance(args, dict):
        raise TypeError("Invalid isolated worker request")
    # The descriptor is generated by the parent from a trusted registered tool;
    # it is never accepted directly from a user task or mission JSON.
    tool, action, mode = pickle.loads(base64.b64decode(descriptor, validate=True))
    if not isinstance(action, str) or mode not in {"tool", "shell_structured"}:
        raise ValueError("Invalid trusted action descriptor")
    if mode == "shell_structured":
        command = args.get("command") or args.get("cmd") or args.get("executable")
        if not isinstance(command, str):
            raise ValueError("shell.run requires a string command")
        result = tool.run(command, cwd_override=args.get("cwd"), timeout=args.get("timeout"))
        output = {
            "command": result.command,
            "stdout": result.stdout,
            "stderr": result.stderr,
            "exit_code": result.return_code if not result.blocked and not result.timed_out else None,
            "blocked": result.blocked,
            "blocked_reason": result.blocked_reason,
            "timed_out": result.timed_out,
        }
    else:
        output = tool.execute(action, args)
    # The outer response is a small protocol envelope; tool output is data.
    return {"ok": True, "result": output}


def main() -> int:
    try:
        request = json.load(sys.stdin)
        if not isinstance(request, dict):
            raise TypeError("Request must be a JSON object")
        response = _execute(request)
    except Exception as exc:  # noqa: BLE001 - serialize any tool exception at the process boundary
        response = {
            "ok": False,
            "error": f"{type(exc).__name__}: {exc}",
        }
    try:
        print(_RESULT_PREFIX + json.dumps(response, ensure_ascii=False, default=str), flush=True)
    except (OSError, TypeError, ValueError):
        print(_RESULT_PREFIX + json.dumps({"ok": False, "error": "Could not serialize worker result"}), flush=True)
        return 1
    return 0 if response.get("ok") else 1


if __name__ == "__main__":
    raise SystemExit(main())
